from datetime import datetime, timedelta

TICKETS_DIR = "/workspace/tickets"
TODAY = datetime(2024, 4, 15)
CUTOFF_DAYS = 90


def closed_date(content):
    for line in content.splitlines():
        if line.startswith("Closed Date:"):
            return datetime.strptime(line.split(":", 1)[1].strip(), "%Y-%m-%d")
    return None


def main():
    cutoff = TODAY - timedelta(days=CUTOFF_DAYS)
    for name in sorted(os.listdir(TICKETS_DIR)):
        if not name.endswith(".txt"):
            continue
        path = os.path.join(TICKETS_DIR, name)
        with open(path) as f:
            content = f.read()
        if "Status: closed" not in content:
            continue
        cd = closed_date(content)
        if cd and cd < cutoff:
            os.remove(path)
            print(f"Removed {name}")


if __name__ == "__main__":
    main()
